def apply_nero_overrides(pool: list[dict]) -> list[dict]:
    result = []
    for question in pool:
        item = deepcopy(question)
        override = NERO_OVERRIDES.get(str(item.get("id") or "").strip())
        if override:
            item.update(deepcopy(override))
        result.append(item)
    return result
